-- BuildPulse Marketplace + Connections core. Payment custody must remain with a regulated marketplace provider.
create table if not exists public.buildpulse_marketplace_listings(id uuid primary key default gen_random_uuid(),seller_id uuid not null references auth.users(id) on delete cascade,category text not null check(category in ('vehicles','property','computers','electronics','fashion','home_garden','collectibles','sports','art','other')),title text not null check(char_length(title) between 3 and 160),description text not null check(char_length(description) between 20 and 10000),price_amount numeric(14,2) not null check(price_amount>=0),currency text not null default 'EUR',condition text check(condition in ('new','like_new','good','fair','for_parts','not_applicable')),media_urls text[] not null default '{}',country_code text,region text,city text,delivery_methods text[] not null default '{}',status text not null default 'draft' check(status in ('draft','submitted','review','active','reserved','sold','rejected','withdrawn','expired')),moderation_flags jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz);
alter table public.buildpulse_marketplace_listings enable row level security;
create policy bp_market_own_select on public.buildpulse_marketplace_listings for select to authenticated using(seller_id=(select auth.uid()));create policy bp_market_own_insert on public.buildpulse_marketplace_listings for insert to authenticated with check(seller_id=(select auth.uid()));create policy bp_market_own_update on public.buildpulse_marketplace_listings for update to authenticated using(seller_id=(select auth.uid()) and status in ('draft','submitted','review','active')) with check(seller_id=(select auth.uid()));create policy bp_market_public_active on public.buildpulse_marketplace_listings for select to anon using(status='active');grant select on public.buildpulse_marketplace_listings to anon;grant select,insert,update on public.buildpulse_marketplace_listings to authenticated;grant all on public.buildpulse_marketplace_listings to service_role;
create table if not exists public.buildpulse_marketplace_orders(id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.buildpulse_marketplace_listings(id),buyer_id uuid not null references auth.users(id),seller_id uuid not null references auth.users(id),amount numeric(14,2) not null,currency text not null,platform_fee numeric(14,2) not null default 0,payment_provider text,status text not null default 'created' check(status in ('created','payment_pending','paid_provider','seller_action','shipped','delivered','disputed','refund_pending','refunded','payout_pending','completed','cancelled')),provider_payment_id text,provider_transfer_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.buildpulse_marketplace_orders enable row level security;create policy bp_market_order_parties on public.buildpulse_marketplace_orders for select to authenticated using(buyer_id=(select auth.uid()) or seller_id=(select auth.uid()));revoke all on public.buildpulse_marketplace_orders from anon;grant select on public.buildpulse_marketplace_orders to authenticated;grant all on public.buildpulse_marketplace_orders to service_role;
create table if not exists public.buildpulse_connections_profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null,bio text check(char_length(bio)<=1500),intents text[] not null default '{}',adult_confirmed boolean not null default false,country_code text,region text,city text,visibility text not null default 'private' check(visibility in ('private','members','public')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.buildpulse_connections_profiles enable row level security;create policy bp_connections_own on public.buildpulse_connections_profiles for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));create policy bp_connections_members on public.buildpulse_connections_profiles for select to authenticated using(visibility in ('members','public'));grant select,insert,update,delete on public.buildpulse_connections_profiles to authenticated;grant all on public.buildpulse_connections_profiles to service_role;
create table if not exists public.buildpulse_user_safety_actions(id uuid primary key default gen_random_uuid(),actor_id uuid not null references auth.users(id),target_id uuid not null references auth.users(id),action text not null check(action in ('block','report')),reason text,created_at timestamptz not null default now(),unique(actor_id,target_id,action));alter table public.buildpulse_user_safety_actions enable row level security;create policy bp_safety_own on public.buildpulse_user_safety_actions for all to authenticated using(actor_id=(select auth.uid())) with check(actor_id=(select auth.uid()));grant select,insert,delete on public.buildpulse_user_safety_actions to authenticated;grant all on public.buildpulse_user_safety_actions to service_role;